16	using hybrid::AndesCaps;
17	using hybrid::AndesGate;
18	
19	// ax45mpv_premium config.inc: CoDense + ILM + DLM + perf monitor on
20	// (NDS_PERFORMANCE_MONITOR_INT=1); NDS_SSCOFPMF_SUPPORT=0 so the Andes PMNDS
21	// counter scheme is live (PMNDS gate on); DSP, ECC, PowerBrake, StackSafe,
22	// PMA off; M-only (NDS_NUM_PRIVILEGE_LEVELS=1 -> UMODE + PMNDS_UMODE off).
23	static AndesCaps premium()
24	{
25	  AndesCaps c = AndesCaps::none();
26	  c.set(AndesGate::CODENSE);
27	  c.set(AndesGate::ILM);
28	  c.set(AndesGate::DLM);
29	  c.set(AndesGate::PERF_MONITOR);
30	  c.set(AndesGate::PMNDS);
31	  c.set(AndesGate::CCTL);    // 64K I$/D$ -> cache CCTL CSRs exist
32	  c.set(AndesGate::ALT_FP);  // NDS_BFLOAT16_ARITH_SUPPORT=1 + ACE
33	  return c;
34	}
35	
36	// ax46mpv_advanced config.inc: perf monitor on BUT NDS_SSCOFPMF_SUPPORT=1 --
37	// the standard Sscofpmf scheme replaces the Andes PMNDS counter CSRs, so the
38	// PMNDS gates stay off. CoDense + ILM + DLM + PMA on; M-only.
39	static AndesCaps advanced()
40	{
41	  AndesCaps c = AndesCaps::none();
42	  c.set(AndesGate::CODENSE);
43	  c.set(AndesGate::ILM);
44	  c.set(AndesGate::DLM);
45	  c.set(AndesGate::PERF_MONITOR);
46	  c.set(AndesGate::PMA);
47	  c.set(AndesGate::TRIGGER);
48	  c.set(AndesGate::CCTL);    // 64K I$/D$
49	  c.set(AndesGate::ALT_FP);  // BF16 arith + ACE
50	  return c;
51	}
52	
53	TEST_CASE("registration audit: the three under-claim classes are gated right")
54	{
55	  // Found by the ax46mpv_advanced registration audit (both engines'
56	  // kv_csr_dec.v existent_csr agree with the SPA on all three):
57	  // 1. mnvec 0x7C3: spec "IM Requirement: Required", RTL unconditional --
58	  //    it is base Andes NMI state, NOT part of Smrnmi (0x740-0x744, which
59	  //    these cores genuinely lack).
60	  CHECK(AndesCaps::none().supports_csr(0x7C3));   // ALWAYS
61	  // 2. mcctlbeginaddr/mcctldata: exist with the cache RAMs (RTL:
62	  //    CACHE_SUPPORT_INT), on BOTH engines; the old binding pointed at
63	  //    NDS_CCTLCSR macros no config generation emits.
64	  CHECK(premium().supports_csr(0x7CB));
65	  CHECK(advanced().supports_csr(0x7CD));
66	  CHECK_FALSE(AndesCaps::none().supports_csr(0x7CB));  // cache-less core
67	  // 3. umisc_ctl 0x813: spec ALT_FP_FMT|CST_CTL, RTL BF16_ARITH|ACE --
68	  //    "Access Mode: User and above" is who may TOUCH it, not an existence
69	  //    condition; the old UMODE gate dropped it on both (M-only) engines.
70	  CHECK(premium().supports_csr(0x813));
71	  CHECK(advanced().supports_csr(0x813));
72	  AndesCaps umode_only = AndesCaps::none();
73	  umode_only.set(AndesGate::UMODE);
74	  CHECK_FALSE(umode_only.supports_csr(0x813));    // U-mode alone: no
75	}
76	
77	TEST_CASE("all() transports every Andes CSR (default = no gating)")
78	{
79	  const AndesCaps c = AndesCaps::all();
80	  CHECK(c.supports_csr(0x801));  // ucode
81	  CHECK(c.supports_csr(0x7C2));  // mecc_code
82	  CHECK(c.supports_csr(0x800));  // uitb
83	}
84	
85	TEST_CASE("premium skips the CSRs its config lacks -- no hang")
86	{
87	  const AndesCaps c = premium();
88	  CHECK_FALSE(c.supports_csr(0x801));  // ucode      (DSP off)  -- the hang case
89	  CHECK_FALSE(c.supports_csr(0x7C2));  // mecc_code  (ECC off)  -- the hang case
90	  CHECK_FALSE(c.supports_csr(0x7C5));  // mpft_ctl   (PowerBrake off)
91	  CHECK_FALSE(c.supports_csr(0x7C6));  // mhsp_ctl   (StackSafe off)
92	  CHECK_FALSE(c.supports_csr(0x7C7));  // msp_bound
93	  CHECK_FALSE(c.supports_csr(0x7C8));  // msp_base
94	  CHECK_FALSE(c.supports_csr(0x7D1));  // mcountermask_m (M-only: needs U-mode)
95	  CHECK_FALSE(c.supports_csr(HYBRID_PMA_ADDR0_CSR));  // pmaaddr0 (PMA off)
96	  CHECK_FALSE(c.supports_csr(HYBRID_PMA_CFG0_CSR));   // pmacfg0
97	}
98	
99	TEST_CASE("the PMNDS counter block needs the Andes scheme, not just a perf "
100	          "monitor: Sscofpmf cores drop it")
101	{
102	  // RTL ground truth (kv_csr_dec.v existent_csr): the PMNDS counter CSRs
103	  // exist iff PERFORMANCE_MONITOR_INT==1 & SSCOFPMF_SUPPORT==0 (+ privilege
104	  // terms) -- the standard Sscofpmf scheme REPLACES them. This is what the
105	  // SPA's `mmsc_cfg.PMNDS` condition compiles down to. ax46mpv_advanced
106	  // (perf monitor on, sscofpmf on) faulted the drain sweep on a csrr of
107	  // mcounterinten 0x7CF when it was gated on PERF_MONITOR alone.
108	  CHECK(premium().supports_csr(0x7CF));         // PMNDS scheme -> exists
109	  CHECK_FALSE(advanced().supports_csr(0x7CF));  // Sscofpmf -> replaced
110	  // The standard counters stay PERF_MONITOR-gated on both schemes.
111	  CHECK(advanced().supports_csr(0x320));        // mcountinhibit
112	  CHECK(advanced().supports_csr(0xB03));        // mhpmcounter3
113	}
114	
115	TEST_CASE("mcountermask_m (0x7D1) needs PMNDS AND U-mode")
116	{
117	  // SPA IM Requirement: (mmsc_cfg.PMNDS==1) & (misa[20]==1) -- the same rule
118	  // as its twins mcountermask_u (0x7D3) and mcounterwen (0x7CE). RTL:
119	  // PERF & !SSCOFPMF & multi_level_mode. An M-only core (premium) or an
120	  // Sscofpmf core (advanced) does not implement them; a PB csrr raises
121	  // cmderr=3, which aborts a whole CSR sweep.
122	  CHECK_FALSE(premium().supports_csr(0x7D1));   // PMNDS but M-only
123	  CHECK_FALSE(advanced().supports_csr(0x7D1));  // U-mode-less AND no PMNDS
124	
125	  AndesCaps pmnds_u = premium();
126	  pmnds_u.set(AndesGate::UMODE);
127	  CHECK_FALSE(pmnds_u.supports_csr(0x7D1));     // UMODE alone is not enough
128	  pmnds_u.set(AndesGate::PMNDS_UMODE);
129	  CHECK(pmnds_u.supports_csr(0x7D1));
130	  CHECK(pmnds_u.supports_csr(0x7CE));           // mcounterwen: same rule
131	  CHECK(pmnds_u.supports_csr(0x7D3));           // mcountermask_u: same rule
132	  // mcountermask_s additionally needs S-mode.
133	  CHECK_FALSE(pmnds_u.supports_csr(0x7D2));
134	}
135	
136	TEST_CASE("jvt (0x017) needs Zcmt, not CoDense")
137	{
138	  // jvt is the standard Zcmt table-jump base. Classic Andes CoDense is
139	  // exec.it + uitb (0x800); a CoDense core without Zcmt does not implement
140	  // jvt, and its csrr faulted the drain sweep on ax45mpv_premium. No
141	  // current engine config carries a Zcmt knob, so the gate reads as off.
142	  AndesCaps codense_only = AndesCaps::none();
143	  codense_only.set(AndesGate::CODENSE);
144	  CHECK(codense_only.supports_csr(0x800));       // uitb rides CoDense
145	  CHECK_FALSE(codense_only.supports_csr(0x017)); // jvt does not
146	
147	  AndesCaps with_zcmt = codense_only;
148	  with_zcmt.set(AndesGate::ZCMT);
149	  CHECK(with_zcmt.supports_csr(0x017));
150	}
151	
152	TEST_CASE("premium keeps the CSRs its config has")
153	{
154	  const AndesCaps c = premium();
155	  CHECK(c.supports_csr(0x800));  // uitb     (CoDense on)
156	  CHECK_FALSE(c.supports_csr(0x017));  // jvt: Zcmt, which premium lacks
157	  CHECK(c.supports_csr(0x7C0));  // milmb    (ILM on)
158	  CHECK(c.supports_csr(0x7C1));  // mdlmb    (DLM on)
159	  CHECK(c.supports_csr(0x7C4));  // mxstatus (base machine CSR -> ALWAYS)
160	  CHECK(c.supports_csr(0x7DF));  // mclk_ctl (base machine CSR -> ALWAYS)
161	}
162	
163	TEST_CASE("--describe name list reflects the caps")
164	{
165	  const std::vector<std::string> n = hybrid::supported_andes_csr_names(premium());
166	  auto has = [&](const char* s) {
167	    return std::find(n.begin(), n.end(), s) != n.end();
168	  };
169	  CHECK(has("uitb"));
170	  CHECK(has("milmb"));
171	  CHECK_FALSE(has("ucode"));
172	  CHECK_FALSE(has("mecc_code"));
173	
174	  // PMA group markers ("pmacfg"/"pmaaddr") are emitted only when PMA is on, so
175	  // the driver can verify-exclude the whole PMA block on a core that lacks it.
176	  CHECK_FALSE(has("pmacfg"));   // premium: PMA off
177	  CHECK_FALSE(has("pmaaddr"));
178	  const std::vector<std::string> all = hybrid::supported_andes_csr_names(AndesCaps::all());
179	  auto all_has = [&](const char* s) {
180	    return std::find(all.begin(), all.end(), s) != all.end();
181	  };
182	  CHECK(all_has("pmacfg"));
183	  CHECK(all_has("pmaaddr"));
184	}
185	
186	TEST_CASE("F6: andes_caps_from_transport_set rebuilds caps from the transported set")
187	{
188	  // The runtime can be driven by the registered manifest instead of config
189	  // macros: the transported set is a union of complete gate-groups, so setting
190	  // each transported CSR's gate reconstructs the EXACT caps. Proven to match the
191	  // config-shape helpers for both built engines -- so config -> caps (from_config)
192	  // and manifest -> caps (from_transport_set) are interchangeable.
193	  for (const AndesCaps want : {premium(), advanced()}) {
194	    std::vector<uint16_t> transported;
195	    for (int a = 0; a <= 0xFFF; ++a) {
196	      const auto addr = static_cast<uint16_t>(a);
197	      if (want.supports_csr(addr)
198	          && hybrid::andes_gate_for(addr) != AndesGate::ALWAYS)
199	        transported.push_back(addr);
200	    }
201	    const AndesCaps rebuilt = hybrid::andes_caps_from_transport_set(transported);
202	    bool identical = true;
203	    for (int a = 0; a <= 0xFFF; ++a) {
204	      const auto addr = static_cast<uint16_t>(a);
205	      if (rebuilt.supports_csr(addr) != want.supports_csr(addr)) identical = false;
206	    }
207	    CHECK(identical);
208	  }
209	}
