_SIZED_HEX_RE = re.compile(r"^\d+'h([0-9a-fA-F]+)$")


def _cpuid(cfg: dict):
    """NDS_CPUID as an int (config.inc carries it as a sized literal 16'h8a66)."""
    raw = (cfg.get("NDS_CPUID") or "").strip()
    m = _SIZED_HEX_RE.match(raw)
    if m:
        return int(m.group(1), 16)
    try:
        return int(raw, 0)
    except ValueError:
        return None


def is_mk_family(cfg: dict) -> bool:
    """mk_core family (AX6x series): the CPUID series nibble is 6. The mk CSR
    decoder (mk_csr_decode.v) diverges from kv_csr_dec.v, so several gates
    bind differently -- mirrors ANDES_CAPS_MK_FAMILY in andes_caps_config.hpp."""
    cpuid = _cpuid(cfg)
    return cpuid is not None and (cpuid & 0xF0) == 0x60


